import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.DMvgf4hZ.js";const k=JSON.parse('{"title":"开发与扩展概览","description":"","frontmatter":{},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md","lastUpdated":1794884041000}'),l={name:"development/index.md"};function o(d,t,i,n,h,p){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="开发与扩展概览" tabindex="-1">开发与扩展概览 <a class="header-anchor" href="#开发与扩展概览" aria-label="Permalink to &quot;开发与扩展概览&quot;">​</a></h1><p>本文收录插件开发、源码运行、桌面打包和更新发布的详细说明。首次参与开发，可先阅读<a href="https://github.com/dolfly/toonflow/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer">贡献指南</a>。</p><ul><li><a href="./setup.html">本地开发与构建</a></li><li><a href="./plugins.html">插件、技能与提供方</a></li><li><a href="./i18n.html">多语言维护</a></li><li><a href="./desktop.html">桌面构建与打包</a></li><li><a href="./structure.html">项目结构</a></li><li><a href="/toonflow/deploy/">部署运维</a></li></ul><h2 id="插件与模型扩展" tabindex="-1">插件与模型扩展 <a class="header-anchor" href="#插件与模型扩展" aria-label="Permalink to &quot;插件与模型扩展&quot;">​</a></h2><p>通过“设置 → 插件市场”发现和管理节点、工具与技能；市场顶部可以直接打开<a href="https://api.toonflow.net/console/plugIn" target="_blank" rel="noreferrer">网页版市场</a>，开发指南见本站<a href="/toonflow/plugins/">插件开发</a> 分区。市场使用“账号与余额”中登录的 Toonflow 账号。</p><table tabindex="0"><thead><tr><th>扩展类型</th><th>用途</th><th>开发入口</th></tr></thead><tbody><tr><td>节点</td><td>为画布增加交互组件、输入输出端口与节点操作。</td><td><a href="https://github.com/dolfly/toonflow/blob/master/packages/nodeScaffold/readme.md" target="_blank" rel="noreferrer">节点脚手架</a> · <a href="https://github.com/dolfly/toonflow/tree/master/packages/nodes" target="_blank" rel="noreferrer">内置节点</a></td></tr><tr><td>工具</td><td>为 Agent 增加工作区操作、搜索、媒体生成等能力，可附带交互 UI。</td><td><a href="https://github.com/dolfly/toonflow/blob/master/packages/toolScaffold/readme.md" target="_blank" rel="noreferrer">工具脚手架</a> · <a href="https://github.com/dolfly/toonflow/tree/master/packages/tools" target="_blank" rel="noreferrer">内置工具</a></td></tr><tr><td>技能</td><td>用 <code>SKILL.md</code> 和附属资料描述创作流程、方法与操作约定。</td><td><a href="https://github.com/dolfly/toonflow/tree/master/packages/skills" target="_blank" rel="noreferrer">内置技能</a></td></tr><tr><td>提供方</td><td>适配不同平台的模型列表、请求参数和媒体返回结果。</td><td><a href="https://github.com/dolfly/toonflow/tree/master/packages/providers/src" target="_blank" rel="noreferrer">提供方实现</a></td></tr></tbody></table><p>节点与工具的配置表单统一使用 <code>@form-create/element-ui</code> 的规则；有必填项未填写时，配置按钮会显示红点。工具只接收自身配置，宿主不向工具直接传递完整应用设置。</p><p>媒体接口包含图片、视频和音频的扩展类型，实际能力由各提供方实现。技能既可以全局安装，也可以放在当前工作区的 <code>skill/</code> 目录，同名时优先使用工作区版本。</p><p>需要从外部 Coding 工具操作 Toonflow 时，在“设置 → MCP”开启服务并复制客户端配置，支持 HTTP 与 stdio 连接。画布和节点等界面操作需要保持 Toonflow 窗口或网页打开，详见 <a href="https://github.com/dolfly/toonflow/blob/master/packages/mcp/README.md" target="_blank" rel="noreferrer">MCP 接入说明</a>。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>前端、业务服务和桌面端在同一个 Bun Workspaces 仓库中维护。</p><table tabindex="0"><thead><tr><th>层级</th><th>技术</th></tr></thead><tbody><tr><td>运行时与包管理</td><td>Bun 1.4.3、Bun Workspaces</td></tr><tr><td>前端</td><td>Vue 3、Vite、TypeScript、Pinia、Element Plus、Vue Flow</td></tr><tr><td>服务端</td><td>Bun、Express 5、Zod</td></tr><tr><td>Agent</td><td>Pi Agent SDK、工具插件、Markdown 技能与记忆</td></tr><tr><td>桌面</td><td>Electrobun；Windows 使用 WebView2 和 NSIS 安装器</td></tr><tr><td>3D 与媒体</td><td>Three.js、FFmpeg、可扩展的媒体提供方</td></tr></tbody></table><h2 id="文档站自身的构建" tabindex="-1">文档站自身的构建 <a class="header-anchor" href="#文档站自身的构建" aria-label="Permalink to &quot;文档站自身的构建&quot;">​</a></h2><p>本站基于 VitePress，源码位于仓库的 <code>docs-site/</code> 目录，图片复用 <code>docs/images/</code>：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 本地预览 http://localhost:5173</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 生成 docs-site/.vitepress/dist</span></span></code></pre></div><p>推送到 <code>master</code>（或手动触发）时，GitHub Actions 会重新构建并发布到 GitHub Pages，流程见<a href="/toonflow/deploy/release.html">版本发布与 CI</a>。</p>`,16)])])}const f=e(l,[["render",o]]);export{k as __pageData,f as default};
